SELECT DATE(usage_start_time, 'Europe/Istanbul') AS day_tsi, service.description AS service, currency, ROUND(SUM(cost),6) AS gross_cost, ROUND(SUM(IFNULL((SELECT SUM(c.amount) FROM UNNEST(credits) c),0)),6) AS credits, ROUND(SUM(cost+IFNULL((SELECT SUM(c.amount) FROM UNNEST(credits) c),0)),6) AS net_cost, COUNT(*) AS row_count, MIN(usage_start_time) AS first_usage, MAX(usage_end_time) AS last_usage FROM `project-27082a40-6083-4952-9db.billing_export.gcp_billing_export_v1_017786_B62E9C_E21182` GROUP BY 1,2,3 ORDER BY 1,2